// ---------------------------------------------------------------------------
// High-level seed functions (composites)
// ---------------------------------------------------------------------------

export type ApiSeedResult = {
  /** The created envelope/document/template. */
  envelope: TGetEnvelopeResponse;
  /** API token for further API calls. */
  token: string;
  /** The seeded user. */
  user: ApiSeedContext['user'];
  /** The seeded team. */
  team: ApiSeedContext['team'];
};

export type ApiSeedDocumentOptions = {
  /** Document title. Default: '[TEST] API Document - Draft' */
  title?: string;
  /** Recipients to add to the document. */
  recipients?: ApiRecipient[];
  /** Fields to add per recipient. If provided, must match recipients order. */
  fieldsPerRecipient?: Array<
    Array<{
      type: string;
      page?: number;
      positionX?: number;
      positionY?: number;
      width?: number;
      height?: number;
      fieldMeta?: Record<string, unknown>;
    }>
  >;
  /** External ID for the envelope. */
  externalId?: string;
  /** Document visibility setting. */
  visibility?: string;
  /** Global access auth requirements. */
  globalAccessAuth?: string[];
  /** Global action auth requirements. */
  globalActionAuth?: string[];
  /** Folder ID to place the document in. */
  folderId?: string;
  /** Document meta settings. */
  meta?: TCreateEnvelopePayload['meta'];
  /** Custom PDF file. Default: example.pdf */
  pdfFile?: { name: string; data: Buffer };
  /** Reuse an existing test context instead of creating a new one. */
  context?: ApiSeedContext;
};

/**
 * Create a draft document via API V2.
 *
 * Creates a user, team, API token, and a DRAFT document. Optionally adds
 * recipients and fields.
 *
 * @example
 * ```ts
 * const { envelope, token, user, team } = await apiSeedDraftDocument(request, {
 *   title: 'My Document',
 *   recipients: [{ email: 'signer@test.com', name: 'Test Signer' }],
 * });
 * ```
 */
export const apiSeedDraftDocument = async (
  request: APIRequestContext,
  options: ApiSeedDocumentOptions = {},
): Promise<ApiSeedResult> => {
  const ctx = options.context ?? (await apiCreateTestContext('e2e-draft-doc'));

  // Create the envelope with inline recipients if provided
  const createOptions: ApiSeedEnvelopeOptions = {
    title: options.title ?? '[TEST] API Document - Draft',
    type: 'DOCUMENT',
    externalId: options.externalId,
    visibility: options.visibility,
    globalAccessAuth: options.globalAccessAuth,
    globalActionAuth: options.globalActionAuth,
    folderId: options.folderId,
    meta: options.meta,
    pdfFile: options.pdfFile,
  };

  // If we have recipients but no per-recipient fields, use inline creation
  if (options.recipients && !options.fieldsPerRecipient) {
    createOptions.recipients = options.recipients.map((r) => ({
      ...r,
      role: r.role ?? 'SIGNER',
    }));
  }

  const { id: envelopeId } = await apiCreateEnvelope(request, ctx.token, createOptions);

  // If we need per-recipient fields, add recipients and fields separately
  if (options.recipients && options.fieldsPerRecipient) {
    const recipientsRes = await apiCreateRecipients(request, ctx.token, envelopeId, options.recipients);

    // Get envelope to resolve envelope item IDs
    const envelopeData = await apiGetEnvelope(request, ctx.token, envelopeId);
    const firstItemId = envelopeData.envelopeItems[0]?.id;

    // Create fields for each recipient
    for (const [index, recipientFields] of options.fieldsPerRecipient.entries()) {
      if (recipientFields.length === 0) {
        continue;
      }

      const recipientId = recipientsRes.data[index].id;

      await apiCreateFields(
        request,
        ctx.token,
        envelopeId,
        recipientFields.map((f) => ({
          ...f,
          recipientId,
          envelopeItemId: firstItemId,
          type: f.type,
        })),
      );
    }
  }

  const envelope = await apiGetEnvelope(request, ctx.token, envelopeId);

  return { envelope, token: ctx.token, user: ctx.user, team: ctx.team };
};

export type ApiSeedPendingDocumentOptions = ApiSeedDocumentOptions & {
  /** Distribution meta (subject, message, etc.). */
  distributeMeta?: TDistributeEnvelopeRequest['meta'];
};

/**
 * Seed a pending (distributed) document via API V2.
 *
 * Creates the document, adds recipients with SIGNATURE fields, then
 * distributes (sends) it. The response includes signing URLs for each
 * recipient.
 *
 * Every SIGNER recipient must have at least one SIGNATURE field for
 * distribution to succeed. If you don't provide `fieldsPerRecipient`,
 * a default SIGNATURE field is added for each SIGNER/APPROVER recipient.
 *
 * @example
 * ```ts
 * const { envelope, distributeResult, token } = await apiSeedPendingDocument(request, {
 *   recipients: [
 *     { email: 'signer@test.com', name: 'Signer' },
 *     { email: 'viewer@test.com', name: 'Viewer', role: 'VIEWER' },
 *   ],
 * });
 *
 * // Access signing URL:
 * const signingUrl = distributeResult.recipients[0].signingUrl;
 * ```
 */
export const apiSeedPendingDocument = async (
  request: APIRequestContext,
  options: ApiSeedPendingDocumentOptions = {},
): Promise<
  ApiSeedResult & {
    distributeResult: TDistributeEnvelopeResponse;
  }
> => {
  const ctx = options.context ?? (await apiCreateTestContext('e2e-pending-doc'));

  const recipients = options.recipients ?? [
    {
      email: `signer-${Date.now()}@test.documenso.com`,
      name: 'Test Signer',
      role: 'SIGNER' as const,
    },
  ];

  // Create the base envelope
  const { id: envelopeId } = await apiCreateEnvelope(request, ctx.token, {
    title: options.title ?? '[TEST] API Document - Pending',
    type: 'DOCUMENT',
    externalId: options.externalId,
    visibility: options.visibility,
    globalAccessAuth: options.globalAccessAuth,
    globalActionAuth: options.globalActionAuth,
    folderId: options.folderId,
    meta: options.meta,
    pdfFile: options.pdfFile,
  });

  // Add recipients
  const recipientsRes = await apiCreateRecipients(request, ctx.token, envelopeId, recipients);

  // Get envelope for item IDs
  const envelopeData = await apiGetEnvelope(request, ctx.token, envelopeId);
  const firstItemId = envelopeData.envelopeItems[0]?.id;

  // Add fields
  if (options.fieldsPerRecipient) {
    for (const [index, recipientFields] of options.fieldsPerRecipient.entries()) {
      if (recipientFields.length === 0) {
        continue;
      }

      await apiCreateFields(
        request,
        ctx.token,
        envelopeId,
        recipientFields.map((f) => ({
          ...f,
          recipientId: recipientsRes.data[index].id,
          envelopeItemId: firstItemId,
          type: f.type,
        })),
      );
    }
  } else {
    // Auto-add a SIGNATURE field for each SIGNER/APPROVER recipient
    const signerFields: ApiField[] = [];

    for (const [index, r] of recipientsRes.data.entries()) {
      const role = recipients[index].role ?? 'SIGNER';

      if (role === 'SIGNER' || role === 'APPROVER') {
        signerFields.push({
          recipientId: r.id,
          envelopeItemId: firstItemId,
          type: 'SIGNATURE',
          page: 1,
          positionX: 10,
          positionY: 10 + index * 10,
          width: 15,
          height: 5,
        });
      }
    }

    if (signerFields.length > 0) {
      await apiCreateFields(request, ctx.token, envelopeId, signerFields);
    }
  }

  // Distribute
  const distributeResult = await apiDistributeEnvelope(request, ctx.token, envelopeId, options.distributeMeta);

  const envelope = await apiGetEnvelope(request, ctx.token, envelopeId);

  return {
    envelope,
    distributeResult,
    token: ctx.token,
    user: ctx.user,
    team: ctx.team,
  };
};

export type ApiSeedTemplateOptions = Omit<ApiSeedDocumentOptions, 'folderId'> & {
  /** Folder ID to place the template in. */
  folderId?: string;
};

/**
 * Seed a template via API V2.
 *
 * Creates a TEMPLATE envelope with optional recipients and fields.
 *
 * @example
 * ```ts
 * const { envelope, token } = await apiSeedTemplate(request, {
 *   title: 'My Template',
 *   recipients: [{ email: 'recipient@test.com', name: 'Signer', role: 'SIGNER' }],
 * });
 * ```
 */
export const apiSeedTemplate = async (
  request: APIRequestContext,
  options: ApiSeedTemplateOptions = {},
): Promise<ApiSeedResult> => {
  const ctx = options.context ?? (await apiCreateTestContext('e2e-template'));

  const createOptions: ApiSeedEnvelopeOptions = {
    title: options.title ?? '[TEST] API Template',
    type: 'TEMPLATE',
    externalId: options.externalId,
    visibility: options.visibility,
    globalAccessAuth: options.globalAccessAuth,
    globalActionAuth: options.globalActionAuth,
    folderId: options.folderId,
    meta: options.meta,
    pdfFile: options.pdfFile,
  };

  if (options.recipients && !options.fieldsPerRecipient) {
    createOptions.recipients = options.recipients.map((r) => ({
      ...r,
      role: r.role ?? 'SIGNER',
    }));
  }

  const { id: envelopeId } = await apiCreateEnvelope(request, ctx.token, createOptions);

  if (options.recipients && options.fieldsPerRecipient) {
    const recipientsRes = await apiCreateRecipients(request, ctx.token, envelopeId, options.recipients);

    const envelopeData = await apiGetEnvelope(request, ctx.token, envelopeId);
    const firstItemId = envelopeData.envelopeItems[0]?.id;

    for (const [index, recipientFields] of options.fieldsPerRecipient.entries()) {
      if (recipientFields.length === 0) {
        continue;
      }

      await apiCreateFields(
        request,
        ctx.token,
        envelopeId,
        recipientFields.map((f) => ({
          ...f,
          recipientId: recipientsRes.data[index].id,
          envelopeItemId: firstItemId,
          type: f.type,
        })),
      );
    }
  }

  const envelope = await apiGetEnvelope(request, ctx.token, envelopeId);

  return { envelope, token: ctx.token, user: ctx.user, team: ctx.team };
};

/**
 * Seed a template with a direct link via API V2.
 *
 * Creates a template with a recipient, then creates a direct link for it.
 *
 * @example
 * ```ts
 * const { envelope, directLink, token } = await apiSeedDirectTemplate(request, {
 *   title: 'Direct Template',
 * });
 *
 * // Use directLink.token for the signing URL
 * ```
 */
export const apiSeedDirectTemplate = async (
  request: APIRequestContext,
  options: ApiSeedTemplateOptions & {
    /** Custom recipient for the direct link. Default: a SIGNER placeholder. */
    directRecipient?: ApiRecipient;
  } = {},
): Promise<
  ApiSeedResult & {
    directLink: { id: number; token: string; enabled: boolean; directTemplateRecipientId: number };
  }
> => {
  const recipients = options.recipients ?? [
    options.directRecipient ?? {
      email: 'direct-template-recipient@documenso.com',
      name: 'Direct Template Recipient',
      role: 'SIGNER' as const,
    },
  ];

  const templateResult = await apiSeedTemplate(request, {
    ...options,
    recipients,
  });

  // Find the recipient ID for the direct link
  const directRecipientEmail = options.directRecipient?.email ?? recipients[0].email;

  const directRecipient = templateResult.envelope.recipients.find((r) => r.email === directRecipientEmail);

  if (!directRecipient) {
    throw new Error(`Direct template recipient not found: ${directRecipientEmail}`);
  }

  const numericTemplateId = mapSecondaryIdToTemplateId(templateResult.envelope.secondaryId);

  const directLink = await apiCreateDirectTemplateLink(
    request,
    templateResult.token,
    numericTemplateId,
    directRecipient.id,
  );

  // Re-fetch envelope to include directLink data
  const envelope = await apiGetEnvelope(request, templateResult.token, templateResult.envelope.id);

  return {
    ...templateResult,
    envelope,
    directLink,
  };
};

/**
 * Seed multiple draft documents in parallel for a single user context.
 *
 * Useful for tests that need multiple documents (e.g., bulk actions, find/filter tests).
 *
 * @example
 * ```ts
 * const { documents, token, user, team } = await apiSeedMultipleDraftDocuments(request, [
 *   { title: 'Doc A' },
 *   { title: 'Doc B' },
 *   { title: 'Doc C' },
 * ]);
 * ```
 */
export const apiSeedMultipleDraftDocuments = async (
  request: APIRequestContext,
  documents: ApiSeedDocumentOptions[],
  context?: ApiSeedContext,
): Promise<{
  documents: TGetEnvelopeResponse[];
  token: string;
  user: ApiSeedContext['user'];
  team: ApiSeedContext['team'];
}> => {
  const ctx = context ?? (await apiCreateTestContext('e2e-multi-doc'));

  const results = await Promise.all(
    documents.map(async (docOptions) => apiSeedDraftDocument(request, { ...docOptions, context: ctx })),
  );

  return {
    documents: results.map((r) => r.envelope),
    token: ctx.token,
    user: ctx.user,
    team: ctx.team,
  };
};

import { NEXT_PUBLIC_WEBAPP_URL } from '@documenso/lib/constants/app';
import type { Page } from '@playwright/test';

// Playwright's `APIRequestContext` never sends `Origin`, which the CSRF
// middleware requires on cookie-authenticated mutations.
export const WEBAPP_ORIGIN_HEADERS = {
  Origin: new URL(NEXT_PUBLIC_WEBAPP_URL()).origin,
} as const;

type LoginOptions = {
  page: Page;
  email?: string;
  password?: string;

  /**
   * Where to navigate after login.
   */
  redirectPath?: string;
};

export const apiSignin = async ({
  page,
  email = 'example@documenso.com',
  password = 'password',
  redirectPath = '/',
}: LoginOptions) => {
  const { request } = page.context();

  const csrfToken = await getCsrfToken(page);

  await request.post(`${NEXT_PUBLIC_WEBAPP_URL()}/api/auth/email-password/authorize`, {
    headers: WEBAPP_ORIGIN_HEADERS,
    data: {
      email,
      password,
      csrfToken,
    },
  });

  await page.goto(`${NEXT_PUBLIC_WEBAPP_URL()}${redirectPath}`);
  await page.waitForTimeout(500);
};

export const apiSignout = async ({ page }: { page: Page }) => {
  const { request } = page.context();

  await request.post(`${NEXT_PUBLIC_WEBAPP_URL()}/api/auth/signout`, {
    headers: WEBAPP_ORIGIN_HEADERS,
  });

  await page.goto(`${NEXT_PUBLIC_WEBAPP_URL()}/signin`);
};

const getCsrfToken = async (page: Page) => {
  const { request } = page.context();

  const response = await request.fetch(`${NEXT_PUBLIC_WEBAPP_URL()}/api/auth/csrf`, {
    method: 'get',
  });

  const { csrfToken } = await response.json();

  if (!csrfToken) {
    throw new Error('Invalid session');
  }

  return csrfToken;
};

export const checkSessionValid = async (page: Page): Promise<boolean> => {
  const { request } = page.context();

  const response = await request.fetch(`${NEXT_PUBLIC_WEBAPP_URL()}/api/auth/session`, {
    method: 'get',
  });

  const session = await response.json();

  return session.isAuthenticated === true;
};

import { prisma } from '@documenso/prisma';
import type { Envelope, Recipient } from '@prisma/client';
import { verifyAuthenticationResponse } from '@simplewebauthn/server';
import { isoBase64URL } from '@simplewebauthn/server/helpers';
import { match } from 'ts-pattern';
import { AppError, AppErrorCode } from '../../errors/app-error';
import type { TDocumentAuth, TDocumentAuthMethods } from '../../types/document-auth';
import { DocumentAuth } from '../../types/document-auth';
import type { TAuthenticationResponseJSONSchema } from '../../types/webauthn';
import { getAuthenticatorOptions } from '../../utils/authenticator';
import { extractDocumentAuthMethods } from '../../utils/document-auth';
import { validateTwoFactorTokenFromEmail } from '../2fa/email/validate-2fa-token-from-email';
import { verifyTwoFactorAuthenticationToken } from '../2fa/verify-2fa-token';
import { verifyPassword } from '../2fa/verify-password';

type IsRecipientAuthorizedOptions = {
  // !: Probably find a better name than 'ACCESS_2FA' if requirements change.
  type: 'ACCESS' | 'ACCESS_2FA' | 'ACTION';
  documentAuthOptions: Envelope['authOptions'];
  recipient: Pick<Recipient, 'authOptions' | 'email' | 'envelopeId'>;

  /**
   * The ID of the user who initiated the request.
   */
  userId?: number;

  /**
   * The auth details to check.
   *
   * Optional because there are scenarios where no auth options are required such as
   * using the user ID.
   */
  authOptions?: TDocumentAuthMethods;
};

const getUserByEmail = async (email: string) => {
  return await prisma.user.findFirst({
    where: {
      email,
    },
    select: {
      id: true,
    },
  });
};

/**
 * Whether the recipient is authorized to perform the requested operation on a
 * document, given the provided auth options.
 *
 * @returns True if the recipient can perform the requested operation.
 */
export const isRecipientAuthorized = async ({
  type,
  documentAuthOptions,
  recipient,
  userId,
  authOptions,
}: IsRecipientAuthorizedOptions): Promise<boolean> => {
  const { derivedRecipientAccessAuth, derivedRecipientActionAuth } = extractDocumentAuthMethods({
    documentAuth: documentAuthOptions,
    recipientAuth: recipient.authOptions,
  });

  const authMethods: TDocumentAuth[] = match(type)
    .with('ACCESS', () => derivedRecipientAccessAuth)
    .with('ACCESS_2FA', () => derivedRecipientAccessAuth)
    .with('ACTION', () => derivedRecipientActionAuth)
    .exhaustive();

  // Early true return when auth is not required.
  if (authMethods.length === 0 || authMethods.some((method) => method === DocumentAuth.EXPLICIT_NONE)) {
    return true;
  }

  // Early true return for ACCESS auth if all methods are 2FA since validation happens in ACCESS_2FA.
  if (type === 'ACCESS' && authMethods.every((method) => method === DocumentAuth.TWO_FACTOR_AUTH)) {
    return true;
  }

  // Create auth options when none are passed for account.
  if (!authOptions && authMethods.some((method) => method === DocumentAuth.ACCOUNT)) {
    authOptions = {
      type: DocumentAuth.ACCOUNT,
    };
  }

  // Authentication required does not match provided method.
  if (!authOptions || !authMethods.includes(authOptions.type)) {
    return false;
  }

  return await match(authOptions)
    .with({ type: DocumentAuth.ACCOUNT }, async () => {
      if (!userId) {
        return false;
      }

      const recipientUser = await getUserByEmail(recipient.email);

      if (!recipientUser) {
        return false;
      }

      return recipientUser.id === userId;
    })
    .with({ type: DocumentAuth.PASSKEY }, async ({ authenticationResponse, tokenReference }) => {
      if (!userId) {
        return false;
      }

      return await isPasskeyAuthValid({
        userId,
        authenticationResponse,
        tokenReference,
      });
    })
    .with({ type: DocumentAuth.TWO_FACTOR_AUTH }, async ({ token, method }) => {
      if (type === 'ACCESS') {
        return true;
      }

      if (type === 'ACCESS_2FA' && method === 'email') {
        return await validateTwoFactorTokenFromEmail({
          envelopeId: recipient.envelopeId,
          email: recipient.email,
          code: token,
          window: 10, // 5 minutes worth of tokens
        });
      }

      if (!userId) {
        return false;
      }

      const user = await prisma.user.findFirst({
        where: {
          id: userId,
        },
      });

      // Should not be possible.
      if (!user) {
        throw new AppError(AppErrorCode.NOT_FOUND, {
          message: 'User not found',
        });
      }

      // For ACTION auth or authenticator method, use TOTP
      return await verifyTwoFactorAuthenticationToken({
        user,
        totpCode: token,
        window: 10, // 5 minutes worth of tokens
      });
    })
    .with({ type: DocumentAuth.PASSWORD }, async ({ password }) => {
      if (!userId) {
        return false;
      }

      return await verifyPassword({
        userId,
        password,
      });
    })
    .with({ type: DocumentAuth.EXPLICIT_NONE }, () => {
      return true;
    })
    .exhaustive();
};

type VerifyPasskeyOptions = {
  /**
   * The ID of the user who initiated the request.
   */
  userId: number;

  /**
   * The secondary ID of the verification token.
   */
  tokenReference: string;

  /**
   * The response from the passkey authenticator.
   */
  authenticationResponse: TAuthenticationResponseJSONSchema;
};

/**
 * Whether the provided passkey authenticator response is valid and the user is
 * authenticated.
 */
const isPasskeyAuthValid = async (options: VerifyPasskeyOptions): Promise<boolean> => {
  return verifyPasskey(options)
    .then(() => true)
    .catch(() => false);
};

/**
 * Verifies whether the provided passkey authenticator is valid and the user is
 * authenticated.
 *
 * Will throw an error if the user should not be authenticated.
 */
const verifyPasskey = async ({
  userId,
  tokenReference,
  authenticationResponse,
}: VerifyPasskeyOptions): Promise<void> => {
  const passkey = await prisma.passkey.findFirst({
    where: {
      credentialId: new Uint8Array(Buffer.from(authenticationResponse.id, 'base64')),
      userId,
    },
  });

  if (!passkey) {
    throw new AppError(AppErrorCode.NOT_FOUND, {
      message: 'Passkey not found',
    });
  }

  const verificationToken = await prisma.verificationToken
    .delete({
      where: {
        userId,
        secondaryId: tokenReference,
      },
    })
    .catch(() => null);

  if (!verificationToken) {
    throw new AppError(AppErrorCode.NOT_FOUND, {
      message: 'Token not found',
    });
  }

  if (verificationToken.expires < new Date()) {
    throw new AppError(AppErrorCode.EXPIRED_CODE, {
      message: 'Token expired',
    });
  }

  const { rpId, origin } = getAuthenticatorOptions();

  const verification = await verifyAuthenticationResponse({
    response: authenticationResponse,
    expectedChallenge: verificationToken.token,
    expectedOrigin: origin,
    expectedRPID: rpId,
    credential: {
      id: isoBase64URL.fromBuffer(passkey.credentialId),
      publicKey: new Uint8Array(passkey.credentialPublicKey),
      counter: Number(passkey.counter),
    },
  }).catch(() => null); // May want to log this for insights.

  if (verification?.verified !== true) {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'User is not authorized',
    });
  }

  await prisma.passkey.update({
    where: {
      id: passkey.id,
    },
    data: {
      lastUsedAt: new Date(),
      counter: verification.authenticationInfo.newCounter,
    },
  });
};

import { RecipientRole } from '@prisma/client';
import { describe, expect, it } from 'vitest';

import {
  assignOmittedRecipientSigningOrders,
  resolveReplacedRecipientSigningOrders,
} from './assign-omitted-recipient-signing-orders';

const signer = (signingOrder?: number | null, id?: number) => ({
  id,
  role: RecipientRole.SIGNER,
  signingOrder,
});

const cc = () => ({ role: RecipientRole.CC, signingOrder: undefined });

const ordersOf = (recipients: Array<{ signingOrder?: number | null }>) =>
  recipients.map((recipient) => recipient.signingOrder);

describe('assignOmittedRecipientSigningOrders', () => {
  it('numbers omitted orders after the highest explicit order, in request order', () => {
    const result = assignOmittedRecipientSigningOrders({
      recipients: [signer(), signer(4), signer(), signer(1)],
    });

    expect(ordersOf(result)).toEqual([5, 4, 6, 1]);
  });

  it('continues after the highest order already on the envelope and never numbers CC recipients', () => {
    const result = assignOmittedRecipientSigningOrders({
      recipients: [cc(), signer(), signer()],
      existingRecipients: [signer(2), signer(7), cc()],
    });

    expect(ordersOf(result)).toEqual([undefined, 8, 9]);
  });

  it('leaves additions unordered when a signing recipient on the envelope has no order', () => {
    const result = assignOmittedRecipientSigningOrders({
      recipients: [signer(), signer(9)],
      existingRecipients: [signer(1), signer(null)],
    });

    expect(ordersOf(result)).toEqual([undefined, 9]);
  });
});

describe('resolveReplacedRecipientSigningOrders', () => {
  const existingRecipients = [signer(1, 10), signer(2, 11)] as Array<{
    id: number;
    role: RecipientRole;
    signingOrder: number | null;
  }>;

  it('keeps the persisted order of a recipient whose order was omitted', () => {
    const { recipients, requestedOrderRecipients } = resolveReplacedRecipientSigningOrders({
      recipients: [signer(undefined, 11), signer(undefined, 10)],
      existingRecipients,
    });

    expect(ordersOf(recipients)).toEqual([2, 1]);
    expect(requestedOrderRecipients).toEqual([]);
  });

  it('numbers new recipients after the kept ones and reports explicitly requested orders', () => {
    const { recipients, requestedOrderRecipients } = resolveReplacedRecipientSigningOrders({
      recipients: [signer(undefined, 10), signer(), signer(5, 11), signer()],
      existingRecipients,
    });

    expect(ordersOf(recipients)).toEqual([1, 6, 5, 7]);
    expect(requestedOrderRecipients).toEqual([recipients[2]]);
  });

  it('does not report an unchanged persisted order as requested', () => {
    const { requestedOrderRecipients } = resolveReplacedRecipientSigningOrders({
      recipients: [signer(1, 10), signer(3)],
      existingRecipients,
    });

    expect(ordersOf(requestedOrderRecipients)).toEqual([3]);
  });
});

import { RecipientRole } from '@prisma/client';
import { describe, expect, it } from 'vitest';

import { SignatureLevel } from '../../types/signature-level';
import { assertCompatibleRecipientGrouping } from './assert-compatible-recipient-grouping';

type TestRecipient = { role: RecipientRole; signingOrder?: number | null };

const signer = (signingOrder?: number | null): TestRecipient => ({ role: RecipientRole.SIGNER, signingOrder });
const cc = (signingOrder?: number | null): TestRecipient => ({ role: RecipientRole.CC, signingOrder });

const expectRejected = (
  signatureLevel: string,
  recipients: TestRecipient[],
  existingRecipients: TestRecipient[] = [],
) => {
  expect(() => assertCompatibleRecipientGrouping({ signatureLevel, recipients, existingRecipients })).toThrow(
    /signing group|same signing step/i,
  );
};

const expectAccepted = (
  signatureLevel: string,
  recipients: TestRecipient[],
  existingRecipients: TestRecipient[] = [],
) => {
  expect(() => assertCompatibleRecipientGrouping({ signatureLevel, recipients, existingRecipients })).not.toThrow();
};

describe('assertCompatibleRecipientGrouping', () => {
  describe('AES/QES envelopes', () => {
    for (const signatureLevel of [SignatureLevel.AES, SignatureLevel.QES]) {
      it(`rejects two signers sharing an explicit signing order (${signatureLevel})`, () => {
        expectRejected(signatureLevel, [signer(1), signer(2), signer(2)]);
      });

      it(`accepts distinct signing orders (${signatureLevel})`, () => {
        expectAccepted(signatureLevel, [signer(1), signer(2), signer(3)]);
      });
    }

    it('rejects a new signer joining a step that already exists on the envelope', () => {
      expectRejected(SignatureLevel.AES, [signer(1)], [signer(1)]);
    });

    it('accepts any number of signers without a signing order', () => {
      expectAccepted(SignatureLevel.AES, [signer(), signer(null), signer(undefined)]);
      expectAccepted(SignatureLevel.AES, [signer(1), signer(), signer()], [signer(null), signer(null)]);
    });

    it('does not validate untouched existing recipients against each other', () => {
      expectAccepted(SignatureLevel.AES, [signer(3)], [signer(1), signer(1)]);
    });

    it('ignores CC recipients', () => {
      expectAccepted(SignatureLevel.AES, [signer(1), cc(1), cc(1)], [cc(1)]);
    });
  });

  describe('SES envelopes', () => {
    it('permits signing groups', () => {
      expectAccepted(SignatureLevel.SES, [signer(1), signer(2), signer(2)], [signer(2)]);
    });
  });
});

