describe('editor operations behind a locked unordered recipient', () => {
  const frozen = () => [
    { id: 1, formId: 'locked', role: RecipientRole.SIGNER, signingOrder: null },
    { id: 2, formId: 'b', role: RecipientRole.SIGNER, signingOrder: null },
    { id: 3, formId: 'c', role: RecipientRole.SIGNER, signingOrder: null },
  ];

  const canUpdate = (r: { formId: string }) => r.formId !== 'locked';

  const positions = (signers: Array<{ formId: string; signingOrder?: number }>) =>
    signers.map((signer) => [signer.formId, signer.signingOrder]);

  const expected = [
    ['locked', undefined],
    ['b', undefined],
    ['c', undefined],
  ];

  it('refuses to number or move anything', () => {
    expect(positions(reorderStep(frozen(), 2, 1, canUpdate))).toEqual(expected);
    expect(positions(extractRecipientToNewStep(frozen(), 'b', 3, canUpdate))).toEqual(expected);
    expect(positions(mergeSteps(frozen(), 2, 1, canUpdate))).toEqual(expected);
    expect(positions(moveRecipientToStep(frozen(), 'c', 1, canUpdate))).toEqual(expected);
  });
});

const makeSigners = () => [
  { formId: 'a', role: RecipientRole.SIGNER, signingOrder: 1 },
  { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 2 },
  { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 3 },
  { formId: 'd', role: RecipientRole.SIGNER, signingOrder: 4 },
];

const ordersOf = (signers: Array<{ formId: string; signingOrder?: number }>) =>
  signers.map((signer) => [signer.formId, signer.signingOrder]);

describe('mergeSteps', () => {
  it('merges all members of the source step into the target step', () => {
    const merged = mergeSteps(makeSigners(), 2, 1);

    expect(ordersOf(merged)).toEqual([
      ['a', 1],
      ['b', 2],
      ['c', 2],
      ['d', 3],
    ]);
  });

  it('merges a whole group into another step', () => {
    const signers = [
      { formId: 'a', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'd', role: RecipientRole.SIGNER, signingOrder: 3 },
    ];

    const merged = mergeSteps(signers, 1, 2);

    expect(ordersOf(merged)).toEqual([
      ['a', 1],
      ['d', 2],
      ['b', 2],
      ['c', 2],
    ]);
  });

  it('returns the input unchanged for an invalid step index', () => {
    const signers = makeSigners();

    expect(mergeSteps(signers, 7, 1)).toEqual(signers);
  });
});

describe('moveRecipientToStep', () => {
  it('appends the recipient to the target step members', () => {
    const moved = moveRecipientToStep(makeSigners(), 'a', 2);

    expect(ordersOf(moved)).toEqual([
      ['b', 1],
      ['c', 2],
      ['a', 2],
      ['d', 3],
    ]);
  });

  it('dissolves a group of two when one member joins another step', () => {
    const signers = [
      { formId: 'a', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 2 },
    ];

    const moved = moveRecipientToStep(signers, 'b', 1);

    expect(ordersOf(moved)).toEqual([
      ['a', 1],
      ['c', 2],
      ['b', 2],
    ]);
  });

  it('is a no-op when the recipient is already a member of the target step', () => {
    const signers = makeSigners();

    expect(ordersOf(moveRecipientToStep(signers, 'b', 1))).toEqual(ordersOf(signers));
  });
});

describe('extractRecipientToNewStep', () => {
  it('extracts a group member into its own step at the given gap', () => {
    const signers = [
      { formId: 'a', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'd', role: RecipientRole.SIGNER, signingOrder: 3 },
    ];

    // Gap 2 = before the step containing 'd'.
    const extracted = extractRecipientToNewStep(signers, 'c', 2);

    expect(ordersOf(extracted)).toEqual([
      ['a', 1],
      ['b', 2],
      ['c', 3],
      ['d', 4],
    ]);
  });

  it('extracts to the end for an out-of-bounds gap index', () => {
    const signers = [
      { formId: 'a', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 2 },
    ];

    const extracted = extractRecipientToNewStep(signers, 'a', 99);

    expect(ordersOf(extracted)).toEqual([
      ['b', 1],
      ['c', 2],
      ['a', 3],
    ]);
  });

  it('is a no-op when a solo recipient is dropped into an adjacent gap', () => {
    const signers = makeSigners();

    expect(ordersOf(extractRecipientToNewStep(signers, 'b', 1))).toEqual(ordersOf(signers));
    expect(ordersOf(extractRecipientToNewStep(signers, 'b', 2))).toEqual(ordersOf(signers));
  });
});

describe('reorderStep', () => {
  it('moves a whole group to a new position', () => {
    const signers = [
      { formId: 'a', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'd', role: RecipientRole.SIGNER, signingOrder: 3 },
    ];

    const reordered = reorderStep(signers, 1, 2);

    expect(ordersOf(reordered)).toEqual([
      ['a', 1],
      ['d', 2],
      ['b', 3],
      ['c', 3],
    ]);
  });

  it('keeps a locked step number anchored while others flow around it', () => {
    const signers = [
      { formId: 'locked', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 3 },
    ];

    const reordered = reorderStep(signers, 1, 2, (r) => r.formId !== 'locked');

    expect(ordersOf(reordered)).toEqual([
      ['locked', 1],
      ['c', 2],
      ['b', 3],
    ]);
  });
});

describe('ungroupStep', () => {
  it('splits a group into consecutive standalone steps preserving relative order', () => {
    const signers = [
      { formId: 'a', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 2 },
      { formId: 'd', role: RecipientRole.SIGNER, signingOrder: 3 },
    ];

    const ungrouped = ungroupStep(signers, 1);

    expect(ordersOf(ungrouped)).toEqual([
      ['a', 1],
      ['b', 2],
      ['c', 3],
      ['d', 4],
    ]);
  });

  it('is a no-op on a step with a single member', () => {
    const signers = makeSigners();

    expect(ordersOf(ungroupStep(signers, 0))).toEqual(ordersOf(signers));
  });

  // Splitting a locked step would rewrite persisted orders, so it is refused
  // rather than attempted.
  it('is a no-op on a locked step', () => {
    const signers = [
      { formId: 'locked', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'peer', role: RecipientRole.SIGNER, signingOrder: 1 },
      { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 2 },
    ];

    const result = ungroupStep(signers, 0, (r) => r.formId !== 'locked');

    expect(ordersOf(result)).toEqual([
      ['locked', 1],
      ['peer', 1],
      ['c', 2],
    ]);
  });
});

describe('locked step guards', () => {
  const withLockedHead = () => [
    { formId: 'locked', role: RecipientRole.SIGNER, signingOrder: 1 },
    { formId: 'b', role: RecipientRole.SIGNER, signingOrder: 2 },
    { formId: 'c', role: RecipientRole.SIGNER, signingOrder: 3 },
  ];

  const canUpdate = (r: { formId: string }) => r.formId !== 'locked';

  it('reorderStep refuses to move a step into the locked region', () => {
    const signers = withLockedHead();

    expect(ordersOf(reorderStep(signers, 2, 0, canUpdate))).toEqual(ordersOf(signers));
  });

  it('reorderStep refuses to move a locked step', () => {
    const signers = withLockedHead();

    expect(ordersOf(reorderStep(signers, 0, 2, canUpdate))).toEqual(ordersOf(signers));
  });

  it('extractRecipientToNewStep refuses to insert into the locked region', () => {
    const signers = withLockedHead();

    expect(ordersOf(extractRecipientToNewStep(signers, 'c', 0, canUpdate))).toEqual(ordersOf(signers));
  });

  it('mergeSteps refuses to merge into a locked step', () => {
    const signers = withLockedHead();

    expect(ordersOf(mergeSteps(signers, 2, 0, canUpdate))).toEqual(ordersOf(signers));
  });

  it('moveRecipientToStep refuses to move a recipient into a locked step', () => {
    const signers = withLockedHead();

    expect(ordersOf(moveRecipientToStep(signers, 'c', 0, canUpdate))).toEqual(ordersOf(signers));
  });

  it('still allows reordering entirely within the unlocked tail', () => {
    const signers = withLockedHead();

    expect(ordersOf(reorderStep(signers, 1, 2, canUpdate))).toEqual([
      ['locked', 1],
      ['c', 2],
      ['b', 3],
    ]);
  });
});

describe('isRecipientTurnBySigningOrder', () => {
  const recipient = (
    id: number,
    signingOrder: number | null,
    signingStatus: SigningStatus,
    role: RecipientRole = RecipientRole.SIGNER,
  ) => ({ id, signingOrder, signingStatus, role });

  it('allows both members of the active group regardless of member order', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.SIGNED),
      recipient(2, 2, SigningStatus.NOT_SIGNED),
      recipient(3, 2, SigningStatus.NOT_SIGNED),
      recipient(4, 3, SigningStatus.NOT_SIGNED),
    ];

    expect(isRecipientTurnBySigningOrder(recipients, recipients[1])).toBe(true);
    expect(isRecipientTurnBySigningOrder(recipients, recipients[2])).toBe(true);
    expect(isRecipientTurnBySigningOrder(recipients, recipients[3])).toBe(false);
  });

  it('blocks later steps until every group member has signed', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.SIGNED),
      recipient(2, 2, SigningStatus.SIGNED),
      recipient(3, 2, SigningStatus.NOT_SIGNED),
      recipient(4, 3, SigningStatus.NOT_SIGNED),
    ];

    expect(isRecipientTurnBySigningOrder(recipients, recipients[3])).toBe(false);
  });

  it('treats a rejected recipient in an earlier step as blocking', () => {
    const recipients = [recipient(1, 1, SigningStatus.REJECTED), recipient(2, 2, SigningStatus.NOT_SIGNED)];

    expect(isRecipientTurnBySigningOrder(recipients, recipients[1])).toBe(false);
  });

  it('ignores CC recipients entirely', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.NOT_SIGNED, RecipientRole.CC),
      recipient(2, 2, SigningStatus.NOT_SIGNED),
    ];

    expect(isRecipientTurnBySigningOrder(recipients, recipients[1])).toBe(true);
  });

  it('sequences recipients without a signing order one at a time by id', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.SIGNED),
      recipient(3, null, SigningStatus.NOT_SIGNED),
      recipient(2, null, SigningStatus.NOT_SIGNED),
    ];

    expect(isRecipientTurnBySigningOrder(recipients, recipients[2])).toBe(true);
    expect(isRecipientTurnBySigningOrder(recipients, recipients[1])).toBe(false);
  });

  it('orders group members by id when strictly sequential', () => {
    const recipients = [recipient(2, 1, SigningStatus.NOT_SIGNED), recipient(1, 1, SigningStatus.NOT_SIGNED)];

    expect(isRecipientTurnBySigningOrder(recipients, recipients[0], { strictlySequential: true })).toBe(false);
    expect(isRecipientTurnBySigningOrder(recipients, recipients[1], { strictlySequential: true })).toBe(true);
    expect(isRecipientTurnBySigningOrder(recipients, recipients[0])).toBe(true);
  });
});

describe('getRecipientsInActiveSigningStep', () => {
  const candidate = (
    id: number,
    signingOrder: number | null,
    signingStatus: SigningStatus = SigningStatus.NOT_SIGNED,
    role: RecipientRole = RecipientRole.SIGNER,
  ) => ({ id, signingOrder, signingStatus, role });

  it('returns every pending recipient sharing the lowest order', () => {
    const recipients = [candidate(3, 2), candidate(4, 2), candidate(5, 3)];

    expect(getRecipientsInActiveSigningStep(recipients).map((r) => r.id)).toEqual([3, 4]);
  });

  it('returns an empty array for no pending recipients', () => {
    expect(getRecipientsInActiveSigningStep([])).toEqual([]);
  });

  it('excludes recipients that have already signed', () => {
    const recipients = [candidate(1, 1, SigningStatus.SIGNED), candidate(2, 2)];

    expect(getRecipientsInActiveSigningStep(recipients).map((r) => r.id)).toEqual([2]);
  });

  // A rejected recipient is not pending: advancing to them would re-activate
  // and re-email somebody who declined to sign.
  it('excludes rejected recipients', () => {
    const recipients = [candidate(1, 1, SigningStatus.REJECTED), candidate(2, 2)];

    expect(getRecipientsInActiveSigningStep(recipients).map((r) => r.id)).toEqual([2]);
  });

  it('excludes CC recipients', () => {
    const recipients = [
      candidate(1, 1, SigningStatus.NOT_SIGNED, RecipientRole.CC),
      candidate(2, 2, SigningStatus.NOT_SIGNED),
    ];

    expect(getRecipientsInActiveSigningStep(recipients).map((r) => r.id)).toEqual([2]);
  });

  it('returns an empty array when every recipient is signed or rejected', () => {
    const recipients = [candidate(1, 1, SigningStatus.SIGNED), candidate(2, 2, SigningStatus.REJECTED)];

    expect(getRecipientsInActiveSigningStep(recipients)).toEqual([]);
  });

  it('activates a single unordered recipient at a time, lowest id first', () => {
    const recipients = [candidate(7, null), candidate(5, null), candidate(9, null)];

    expect(getRecipientsInActiveSigningStep(recipients).map((r) => r.id)).toEqual([5]);
  });

  it('activates only the lowest id of a group when strictly sequential', () => {
    const recipients = [candidate(4, 1), candidate(3, 1), candidate(5, 2)];

    expect(getRecipientsInActiveSigningStep(recipients, { strictlySequential: true }).map((r) => r.id)).toEqual([3]);
  });
});

describe('getNextDictatableRecipient', () => {
  const recipient = (
    id: number,
    signingOrder: number | null,
    signingStatus: SigningStatus,
    role: RecipientRole = RecipientRole.SIGNER,
  ) => ({ id, signingOrder, signingStatus, role });

  it('returns the next recipient when current is last of their step and next step is a single recipient', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.SIGNED),
      recipient(2, 2, SigningStatus.NOT_SIGNED),
      recipient(3, 3, SigningStatus.NOT_SIGNED),
    ];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 2 })?.id).toBe(3);
  });

  it('returns null while a group peer is still unsigned', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.NOT_SIGNED),
      recipient(2, 1, SigningStatus.NOT_SIGNED),
      recipient(3, 2, SigningStatus.NOT_SIGNED),
    ];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 1 })).toBeNull();
  });

  it('returns the next single recipient once all group peers signed', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.SIGNED),
      recipient(2, 1, SigningStatus.NOT_SIGNED),
      recipient(3, 2, SigningStatus.NOT_SIGNED),
    ];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 2 })?.id).toBe(3);
  });

  it('returns null when the next step is a group', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.NOT_SIGNED),
      recipient(2, 2, SigningStatus.NOT_SIGNED),
      recipient(3, 2, SigningStatus.NOT_SIGNED),
    ];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 1 })).toBeNull();
  });

  it('returns null when there is no later step, for CC targets, or unknown recipients', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.NOT_SIGNED),
      recipient(2, null, SigningStatus.NOT_SIGNED, RecipientRole.CC),
    ];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 1 })).toBeNull();
    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 999 })).toBeNull();
  });

  // The server picks the next recipient from a pending-only query, so an
  // already-signed recipient in a later step must be skipped here too —
  // otherwise the dictated name/email is applied to someone else.
  it('skips an already-signed recipient sitting in a later step', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.NOT_SIGNED),
      recipient(2, 2, SigningStatus.SIGNED),
      recipient(3, 3, SigningStatus.NOT_SIGNED),
    ];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 1 })?.id).toBe(3);
  });

  it('ignores signed members when deciding whether the next step is a group', () => {
    const recipients = [
      recipient(1, 1, SigningStatus.NOT_SIGNED),
      recipient(2, 2, SigningStatus.SIGNED),
      recipient(3, 2, SigningStatus.NOT_SIGNED),
    ];

    // Only one member of step 2 is still pending, which is what the server would rename.
    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 1 })?.id).toBe(3);
  });

  it('returns null when every later recipient has signed', () => {
    const recipients = [recipient(1, 1, SigningStatus.NOT_SIGNED), recipient(2, 2, SigningStatus.SIGNED)];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 1 })).toBeNull();
  });

  it('treats the next unordered recipient by id as a single-recipient step', () => {
    const recipients = [
      recipient(1, null, SigningStatus.NOT_SIGNED),
      recipient(2, null, SigningStatus.NOT_SIGNED),
      recipient(3, null, SigningStatus.NOT_SIGNED),
    ];

    expect(getNextDictatableRecipient({ recipients, currentRecipientId: 1 })?.id).toBe(2);
  });
});

import { RecipientRole } from '@prisma/client';
import { describe, expect, it } from 'vitest';

import { getLaterSigningStepRecipientsWhereInput, getRecipientFieldsWhereInput } from './recipient-queries';

describe('getLaterSigningStepRecipientsWhereInput', () => {
  it('follows a numbered assistant with higher numbers and every unordered recipient', () => {
    const where = getLaterSigningStepRecipientsWhereInput({ id: 10, signingOrder: 2, envelopeId: 'envelope_1' });

    expect(where).toEqual({
      envelopeId: 'envelope_1',
      OR: [{ signingOrder: { gt: 2 } }, { signingOrder: null }],
    });
  });

  it('follows an unordered assistant with later unordered recipients only', () => {
    const where = getLaterSigningStepRecipientsWhereInput({ id: 10, signingOrder: null, envelopeId: 'envelope_1' });

    expect(where).toEqual({
      envelopeId: 'envelope_1',
      signingOrder: null,
      id: { gt: 10 },
    });
  });

  // `{ gt: undefined }` / `{ gt: NaN }` is silently dropped by Prisma, which
  // would invert the predicate into match-everything. Fail closed instead.
  it('throws when a non-finite id or order bypasses the types', () => {
    expect(() =>
      getLaterSigningStepRecipientsWhereInput({
        id: undefined as unknown as number,
        signingOrder: null,
        envelopeId: 'envelope_1',
      }),
    ).toThrow();

    expect(() =>
      getLaterSigningStepRecipientsWhereInput({ id: 10, signingOrder: NaN, envelopeId: 'envelope_1' }),
    ).toThrow();
  });
});

describe('getRecipientFieldsWhereInput', () => {
  const assistant = {
    id: 10,
    role: RecipientRole.ASSISTANT,
    signingOrder: 2,
    envelopeId: 'envelope_1',
  };

  it('restricts non-assistants and disallowed assistants to their own recipient row', () => {
    expect(
      getRecipientFieldsWhereInput({
        recipient: { ...assistant, role: RecipientRole.SIGNER },
        allowAssistantAccessToOtherRecipients: true,
      }),
    ).toEqual({ id: 10 });

    expect(
      getRecipientFieldsWhereInput({
        recipient: assistant,
        allowAssistantAccessToOtherRecipients: false,
      }),
    ).toEqual({ id: 10 });
  });

  it('scopes assistant access to unsigned recipients positioned after them in the same envelope', () => {
    const where = getRecipientFieldsWhereInput({
      recipient: assistant,
      allowAssistantAccessToOtherRecipients: true,
    });

    expect(where).toEqual({
      signingStatus: { not: 'SIGNED' },
      envelopeId: 'envelope_1',
      AND: [
        {
          envelopeId: 'envelope_1',
          OR: [
            { id: 10 },
            {
              envelopeId: 'envelope_1',
              OR: [{ signingOrder: { gt: 2 } }, { signingOrder: null }],
            },
          ],
        },
      ],
    });
  });
});

import { RecipientRole } from '@prisma/client';
import { describe, expect, it } from 'vitest';

import { isAssistantLastSigner, normalizeRecipientSigningOrders, sortRecipientsForSigningOrder } from './recipients';

describe('recipient signing order helpers', () => {
  it('sorts CC recipients after ordered active recipients', () => {
    const recipients = [
      { id: 1, role: RecipientRole.CC, signingOrder: 1 },
      { id: 2, role: RecipientRole.SIGNER, signingOrder: 2 },
      { id: 3, role: RecipientRole.APPROVER, signingOrder: 1 },
    ];

    expect(sortRecipientsForSigningOrder(recipients).map((recipient) => recipient.id)).toEqual([3, 2, 1]);
  });

  it('keeps original order when recipients have the same signing order', () => {
    const recipients = [
      { id: 2, role: RecipientRole.SIGNER, signingOrder: 1 },
      { id: 1, role: RecipientRole.APPROVER, signingOrder: 1 },
    ];

    expect(sortRecipientsForSigningOrder(recipients).map((recipient) => recipient.id)).toEqual([2, 1]);
  });

  it('sorts recipients without a signing order after numbered ones, by id', () => {
    const recipients = [
      { id: 3, role: RecipientRole.SIGNER, signingOrder: null },
      { id: 4, role: RecipientRole.CC, signingOrder: null },
      { id: 2, role: RecipientRole.SIGNER, signingOrder: null },
      { id: 5, role: RecipientRole.SIGNER, signingOrder: 9 },
    ];

    expect(sortRecipientsForSigningOrder(recipients).map((recipient) => recipient.id)).toEqual([5, 2, 3, 4]);
  });

  it('treats an unordered assistant as last only when no unordered recipient has a higher id', () => {
    expect(
      isAssistantLastSigner([
        { id: 2, role: RecipientRole.ASSISTANT, signingOrder: null },
        { id: 1, role: RecipientRole.SIGNER, signingOrder: null },
        { id: 3, role: RecipientRole.SIGNER, signingOrder: 1 },
      ]),
    ).toBe(true);

    expect(
      isAssistantLastSigner([
        { id: 1, role: RecipientRole.ASSISTANT, signingOrder: null },
        { id: 2, role: RecipientRole.SIGNER, signingOrder: null },
      ]),
    ).toBe(false);
  });

  it('sorts and normalizes active recipient signing order and removes it from CC recipients', () => {
    const recipients = [
      { id: 1, role: RecipientRole.CC, signingOrder: 1 },
      { id: 2, role: RecipientRole.SIGNER, signingOrder: 4 },
      { id: 3, role: RecipientRole.APPROVER, signingOrder: 2 },
    ];

    expect(normalizeRecipientSigningOrders(sortRecipientsForSigningOrder(recipients))).toEqual([
      { id: 3, role: RecipientRole.APPROVER, signingOrder: 1 },
      { id: 2, role: RecipientRole.SIGNER, signingOrder: 2 },
      { id: 1, role: RecipientRole.CC, signingOrder: undefined },
    ]);
  });

  it('preserves caller order while normalizing signing order', () => {
    const recipients = [
      { id: 2, role: RecipientRole.ASSISTANT, signingOrder: 2 },
      { id: 1, role: RecipientRole.SIGNER, signingOrder: 1 },
      { id: 3, role: RecipientRole.CC, signingOrder: 1 },
    ];

    expect(normalizeRecipientSigningOrders(recipients)).toEqual([
      { id: 2, role: RecipientRole.ASSISTANT, signingOrder: 1 },
      { id: 1, role: RecipientRole.SIGNER, signingOrder: 2 },
      { id: 3, role: RecipientRole.CC, signingOrder: undefined },
    ]);
  });

  it('detects an assistant anywhere in the last signing step (groups)', () => {
    expect(
      isAssistantLastSigner([
        { role: RecipientRole.SIGNER, signingOrder: 1 },
        { role: RecipientRole.ASSISTANT, signingOrder: 2 },
        { role: RecipientRole.SIGNER, signingOrder: 2 },
      ]),
    ).toBe(true);

    expect(
      isAssistantLastSigner([
        { role: RecipientRole.ASSISTANT, signingOrder: 1 },
        { role: RecipientRole.SIGNER, signingOrder: 1 },
        { role: RecipientRole.SIGNER, signingOrder: 2 },
      ]),
    ).toBe(false);
  });

  it('checks whether the last non-CC recipient is an assistant', () => {
    expect(
      isAssistantLastSigner([
        { role: RecipientRole.SIGNER },
        { role: RecipientRole.ASSISTANT },
        { role: RecipientRole.CC },
      ]),
    ).toBe(true);

    expect(
      isAssistantLastSigner([
        { role: RecipientRole.ASSISTANT },
        { role: RecipientRole.SIGNER },
        { role: RecipientRole.CC },
      ]),
    ).toBe(false);
  });
});

import { describe, expect, it } from 'vitest';

import { UserAuthMethod } from '../types/user-auth-method';
import { deriveUserAuthMethods } from './user-auth-methods';

describe('deriveUserAuthMethods', () => {
  it('returns an empty list when the user has no sign in methods', () => {
    expect(deriveUserAuthMethods({ hasPassword: false, passkeyCount: 0, accountProviders: [] })).toEqual([]);
  });

  it('includes PASSWORD when the user has a password', () => {
    expect(deriveUserAuthMethods({ hasPassword: true, passkeyCount: 0, accountProviders: [] })).toEqual([
      UserAuthMethod.PASSWORD,
    ]);
  });

  it('includes PASSKEY when the user has at least one passkey', () => {
    expect(deriveUserAuthMethods({ hasPassword: false, passkeyCount: 2, accountProviders: [] })).toEqual([
      UserAuthMethod.PASSKEY,
    ]);
  });

  it('maps built in OAuth providers to their auth method', () => {
    expect(
      deriveUserAuthMethods({
        hasPassword: false,
        passkeyCount: 0,
        accountProviders: ['google', 'microsoft', 'oidc'],
      }),
    ).toEqual([UserAuthMethod.GOOGLE, UserAuthMethod.MICROSOFT, UserAuthMethod.OIDC]);
  });

  it('treats unknown providers as organisation SSO', () => {
    expect(
      deriveUserAuthMethods({
        hasPassword: false,
        passkeyCount: 0,
        accountProviders: ['org_abc123'],
      }),
    ).toEqual([UserAuthMethod.ORGANISATION_SSO]);
  });

  it('deduplicates repeated providers', () => {
    expect(
      deriveUserAuthMethods({
        hasPassword: true,
        passkeyCount: 0,
        accountProviders: ['google', 'google', 'org_a', 'org_b'],
      }),
    ).toEqual([UserAuthMethod.PASSWORD, UserAuthMethod.GOOGLE, UserAuthMethod.ORGANISATION_SSO]);
  });
});

import { sValidator } from '@hono/standard-validator';
import { Hono } from 'hono';
import { z } from 'zod';

import { GoogleAuthOptions, MicrosoftAuthOptions, OidcAuthOptions } from '../config';
import { handleOAuthAuthorizeUrl } from '../lib/utils/handle-oauth-authorize-url';
import { getOrganisationAuthenticationPortalOptions } from '../lib/utils/organisation-portal';
import type { HonoAuthContext } from '../types/context';

const ZOAuthAuthorizeSchema = z.object({
  redirectPath: z.string().optional(),
});

export const oauthRoute = new Hono<HonoAuthContext>()
  /**
   * Google authorize endpoint.
   */
  .post('/authorize/google', sValidator('json', ZOAuthAuthorizeSchema), async (c) => {
    const { redirectPath } = c.req.valid('json');

    return handleOAuthAuthorizeUrl({
      c,
      clientOptions: GoogleAuthOptions,
      redirectPath,
    });
  })

  /**
   * Microsoft authorize endpoint.
   */
  .post('/authorize/microsoft', sValidator('json', ZOAuthAuthorizeSchema), async (c) => {
    const { redirectPath } = c.req.valid('json');

    return handleOAuthAuthorizeUrl({
      c,
      clientOptions: MicrosoftAuthOptions,
      redirectPath,
    });
  })

  /**
   * OIDC authorize endpoint.
   */
  .post('/authorize/oidc', sValidator('json', ZOAuthAuthorizeSchema), async (c) => {
    const { redirectPath } = c.req.valid('json');

    return handleOAuthAuthorizeUrl({
      c,
      clientOptions: OidcAuthOptions,
      redirectPath,
    });
  })
  /**
   * Organisation OIDC authorize endpoint.
   */
  .post('/authorize/oidc/org/:orgUrl', async (c) => {
    const orgUrl = c.req.param('orgUrl');

    const { clientOptions } = await getOrganisationAuthenticationPortalOptions({
      type: 'url',
      organisationUrl: orgUrl,
    });

    return await handleOAuthAuthorizeUrl({
      c,
      clientOptions,
      prompt: 'select_account',
    });
  });

import { prisma } from '@documenso/prisma';
import type { Passkey } from '@prisma/client';
import type { AuthenticatorTransportFuture } from '@simplewebauthn/server';
import { generateAuthenticationOptions } from '@simplewebauthn/server';
import { isoBase64URL } from '@simplewebauthn/server/helpers';
import { DateTime } from 'luxon';

import { AppError, AppErrorCode } from '../../errors/app-error';
import { getAuthenticatorOptions } from '../../utils/authenticator';

type CreatePasskeyAuthenticationOptions = {
  userId: number;

  /**
   * The ID of the passkey to request authentication for.
   *
   * If not set, we allow the browser client to handle choosing.
   */
  preferredPasskeyId?: string;
};

export const createPasskeyAuthenticationOptions = async ({
  userId,
  preferredPasskeyId,
}: CreatePasskeyAuthenticationOptions) => {
  const { rpId, timeout } = getAuthenticatorOptions();

  let preferredPasskey: Pick<Passkey, 'credentialId' | 'transports'> | null = null;

  if (preferredPasskeyId) {
    preferredPasskey = await prisma.passkey.findFirst({
      where: {
        userId,
        id: preferredPasskeyId,
      },
      select: {
        credentialId: true,
        transports: true,
      },
    });

    if (!preferredPasskey) {
      throw new AppError(AppErrorCode.NOT_FOUND, {
        message: 'Requested passkey not found',
      });
    }
  }

  const options = await generateAuthenticationOptions({
    rpID: rpId,
    userVerification: 'preferred',
    timeout,
    allowCredentials: preferredPasskey
      ? [
          {
            id: isoBase64URL.fromBuffer(preferredPasskey.credentialId),
            // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
            transports: preferredPasskey.transports as AuthenticatorTransportFuture[],
          },
        ]
      : undefined,
  });

  const { secondaryId } = await prisma.verificationToken.create({
    data: {
      userId,
      token: [REDACTED],
      expires: DateTime.now().plus({ minutes: 2 }).toJSDate(),
      identifier: 'PASSKEY_CHALLENGE',
    },
  });

  return {
    tokenReference: secondaryId,
    options,
  };
};

import { SignJWT } from 'jose';
import { DateTime } from 'luxon';

import { AppError, AppErrorCode } from '../../errors/app-error';
import { env } from '../../utils/env';
import { getApiTokenByToken } from '../public-api/get-api-token-by-token';

export type CreateEmbeddingPresignTokenOptions = {
  apiToken: string;
  /**
   * Number of hours until the token expires
   * In development mode, can be set to 0 to create a token that expires immediately (for testing)
   */
  expiresIn?: number;
  scope?: string;
};

export const createEmbeddingPresignToken = async ({
  apiToken,
  expiresIn,
  scope,
}: CreateEmbeddingPresignTokenOptions) => {
  try {
    // Validate the API token
    const validatedToken = await getApiTokenByToken({ token: apiToken, bypassRateLimit: true });

    const now = DateTime.now();

    // In development mode, allow setting expiresIn to 0 for testing
    // In production, enforce a minimum expiration time
    const isDevelopment = env('NODE_ENV') !== 'production';
    const minExpirationMinutes = isDevelopment ? 0 : 5;

    // Ensure expiresIn is at least the minimum allowed value
    const effectiveExpiresIn = expiresIn !== undefined && expiresIn >= minExpirationMinutes ? expiresIn : 60; // Default to 1 hour if not specified or below minimum

    const expiresAt = now.plus({ minutes: effectiveExpiresIn });

    const secret = new TextEncoder().encode(validatedToken.token);

    const token = await new SignJWT({
      aud: String(validatedToken.teamId ?? validatedToken.userId),
      sub: String(validatedToken.id),
      scope,
    })
      .setProtectedHeader({ alg: 'HS256' })
      .setIssuedAt(now.toJSDate())
      .setExpirationTime(expiresAt.toJSDate())
      .sign(secret);

    return {
      token,
      expiresAt: expiresAt.toJSDate(),
      expiresIn: Math.floor(expiresAt.diff(now).toMillis() / 1000),
    };
  } catch (error) {
    if (error instanceof AppError) {
      throw error;
    }
    throw new AppError(AppErrorCode.UNKNOWN_ERROR, {
      message: 'Failed to create presign token',
    });
  }
};

import { prisma } from '@documenso/prisma';
import type { JWTPayload } from 'jose';
import { decodeJwt, jwtVerify } from 'jose';

import { AppError, AppErrorCode } from '../../errors/app-error';

export type VerifyEmbeddingPresignTokenOptions = {
  token: string;
  scope?: string;
};

export const verifyEmbeddingPresignToken = async ({ token, scope }: VerifyEmbeddingPresignTokenOptions) => {
  // First decode the JWT to get the claims without verification
  let decodedToken: JWTPayload;

  try {
    decodedToken = [REDACTED];
  } catch (error) {
    console.error('Error decoding JWT token:', error);
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid presign token format',
    });
  }

  // Validate the required claims
  if (!decodedToken.sub || typeof decodedToken.sub !== 'string') {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid presign token format: missing or invalid subject claim',
    });
  }

  if (!decodedToken.aud || typeof decodedToken.aud !== 'string') {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid presign token format: missing or invalid audience claim',
    });
  }

  // Convert string IDs to numbers
  const tokenId = Number(decodedToken.sub);
  const audienceId = Number(decodedToken.aud);

  if (Number.isNaN(tokenId) || !Number.isInteger(tokenId)) {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid token ID format in subject claim',
    });
  }

  if (Number.isNaN(audienceId) || !Number.isInteger(audienceId)) {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid user ID format in audience claim',
    });
  }

  // Get the API token to use as the verification secret
  const apiToken = await prisma.apiToken.findFirst({
    where: {
      id: tokenId,
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          email: true,
        },
      },
    },
  });

  if (!apiToken) {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid presign token: API token not found',
    });
  }

  // This should never happen but we need to narrow types
  if (!apiToken.userId || !apiToken.user) {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid presign token: API token does not have a user attached',
    });
  }

  const userId = apiToken.userId;

  if (audienceId !== apiToken.teamId && audienceId !== apiToken.userId) {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Invalid presign token: API token does not match audience',
    });
  }

  if (decodedToken.scope && scope && decodedToken.scope !== scope) {
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Presign token scope not matched',
    });
  }

  // Now verify the token with the actual secret
  const secret = new TextEncoder().encode(apiToken.token);

  try {
    await jwtVerify(token, secret);
  } catch (error) {
    // Check if the token has expired
    if (error instanceof Error && error.name === 'JWTExpired') {
      throw new AppError(AppErrorCode.UNAUTHORIZED, {
        message: 'Presign token has expired',
      });
    }

    // Handle invalid signature
    if (error instanceof Error && error.name === 'JWSInvalid') {
      throw new AppError(AppErrorCode.UNAUTHORIZED, {
        message: 'Invalid presign token signature',
      });
    }

    // Log and rethrow other errors
    console.error('Error verifying JWT token:', error);
    throw new AppError(AppErrorCode.UNAUTHORIZED, {
      message: 'Failed to verify presign token',
    });
  }

  return {
    ...apiToken,
    userId,
    user: {
      id: apiToken.user.id,
      name: apiToken.user.name,
      email: apiToken.user.email,
    },
  };
};

import type { Recipient } from '@prisma/client';

import { hasSigningOrder, isCcRecipient } from '../../utils/recipients';

type OrderableRecipient = Pick<Recipient, 'role'> & { signingOrder?: number | null };

type AssignOmittedRecipientSigningOrdersOptions<T> = {
  recipients: T[];
  existingRecipients?: OrderableRecipient[];
};

/**
 * Numbers signing recipients created without an order after the highest
 * explicit order on the envelope, in request order.
 */
export const assignOmittedRecipientSigningOrders = <T extends OrderableRecipient>({
  recipients,
  existingRecipients = [],
}: AssignOmittedRecipientSigningOrdersOptions<T>): T[] => {
  // Numbers sort ahead of unordered rows, so numbering an addition would move
  // it in front of a legacy unordered signer. Left unordered it queues behind
  // that tail by id.
  const hasUnorderedExistingSigner = existingRecipients.some(
    (recipient) => !isCcRecipient(recipient) && !hasSigningOrder(recipient),
  );

  if (hasUnorderedExistingSigner) {
    return recipients;
  }

  let highestOrder = 0;

  for (const recipient of [...existingRecipients, ...recipients]) {
    if (hasSigningOrder(recipient)) {
      highestOrder = Math.max(highestOrder, recipient.signingOrder);
    }
  }

  let nextOrder = highestOrder + 1;

  return recipients.map((recipient) => {
    if (isCcRecipient(recipient) || hasSigningOrder(recipient)) {
      return recipient;
    }

    const signingOrder = nextOrder;

    nextOrder += 1;

    return { ...recipient, signingOrder };
  });
};

type ReplacementRecipient = OrderableRecipient & { id?: number | null };

type ResolveReplacedRecipientSigningOrdersOptions<T> = {
  recipients: T[];
  existingRecipients: Array<Pick<Recipient, 'id' | 'role' | 'signingOrder'>>;
};

/**
 * Resolves signing orders for a full recipient replacement (`set*Recipients`):
 * a persisted recipient whose order was omitted keeps it, new recipients are
 * numbered after the kept ones.
 *
 * `requestedOrderRecipients` is the subset whose order differs from what was
 * persisted — the only entries that can form a new signing group.
 */
export const resolveReplacedRecipientSigningOrders = <T extends ReplacementRecipient>({
  recipients,
  existingRecipients,
}: ResolveReplacedRecipientSigningOrdersOptions<T>): { recipients: T[]; requestedOrderRecipients: T[] } => {
  const persistedById = new Map(existingRecipients.map((recipient) => [recipient.id, recipient]));

  const findPersisted = (recipient: T) =>
    typeof recipient.id === 'number' ? persistedById.get(recipient.id) : undefined;

  const preserved = recipients.map((recipient) => {
    const persisted = findPersisted(recipient);

    if (!persisted || hasSigningOrder(recipient)) {
      return recipient;
    }

    return { ...recipient, signingOrder: persisted.signingOrder };
  });

  const keptRecipients = preserved.filter((recipient) => findPersisted(recipient) !== undefined);
  const newRecipients = preserved.filter((recipient) => findPersisted(recipient) === undefined);

  const numberedNewRecipients = assignOmittedRecipientSigningOrders({
    recipients: newRecipients,
    existingRecipients: keptRecipients,
  });

  let numberedIndex = 0;

  const resolved = preserved.map((recipient) => {
    if (findPersisted(recipient) !== undefined) {
      return recipient;
    }

    const numbered = numberedNewRecipients[numberedIndex];

    numberedIndex += 1;

    return numbered;
  });

  const requestedOrderRecipients = resolved.filter((_recipient, index) => {
    const requested = recipients[index];
    const persisted = findPersisted(requested);

    return hasSigningOrder(requested) && (!persisted || persisted.signingOrder !== requested.signingOrder);
  });

  return { recipients: resolved, requestedOrderRecipients };
};

