import sharp from 'sharp';

export const optimiseAvatar = async (bytes: string) => {
  return await sharp(Buffer.from(bytes, 'base64')).resize(512, 512).toFormat('jpeg', { quality: 75 }).toBuffer();
};

export const loadAvatar = async (bytes: string) => {
  const content = await sharp(Buffer.from(bytes, 'base64')).toFormat('jpeg').toBuffer();
  return {
    contentType: 'image/jpeg',
    content,
  };
};

import sharp from 'sharp';

export const loadLogo = async (file: Uint8Array) => {
  const content = await sharp(file).toFormat('png', { quality: 80 }).toBuffer();

  return {
    contentType: 'image/png',
    content,
  };
};

/**
 * Validate and sanitise an uploaded branding logo. Re-encoding through `sharp`
 * proves the bytes are a real raster image and strips any embedded payloads.
 * Throws if the input cannot be parsed as an image.
 */
export const optimiseBrandingLogo = async (input: Buffer | Uint8Array): Promise<Buffer> => {
  return await sharp(input)
    .resize(512, 512, { fit: 'inside', withoutEnlargement: true })
    .png({ quality: 80 })
    .toBuffer();
};

import sharp from 'sharp';

export const TARGET_SIZE = 1000;

type ResizeImageToGeminiImageOptions = {
  image: Buffer;
  size?: number;
};

/**
 * Resize image to 1000x1000 using fill strategy.
 * Scales to cover the target area and crops any overflow.
 */
export const resizeImageToGeminiImage = async ({ image, size = TARGET_SIZE }: ResizeImageToGeminiImageOptions) => {
  return await sharp(image).resize(size, size, { fit: 'fill' }).toBuffer();
};

import sharp from 'sharp';

export const svgToPng = async (svg: string) => {
